            H += (J1/4)*(bond_op(n,i,i+1,sx,sx)+bond_op(n,i,i+1,sy,sy)
                          +bond_op(n,i,i+1,sz,sz))
        for i in range(n - 2):
            H += (J2/4)*(bond_op(n,i,i+2,sx,sx)+bond_op(n,i,i+2,sy,sy)
                          +bond_op(n,i,i+2,sz,sz))
        return H

    def s_ent(psi, n, cut):
        psi_mat = psi.reshape(2**cut, 2**(n - cut))
        _, sv, _ = np.linalg.svd(psi_mat, full_matrices=False)
        sv2 = sv**2; sv2 = sv2[sv2 > 1e-14]
        return float(-np.sum(sv2 * np.log(sv2)))

    def sqmz2(psi, n):
        Sz = sum(site_op(n,i,sz) for i in range(n))
        return np.sqrt(max(0.0, ev(psi, (Sz/n)@(Sz/n))))

    def add_noise(val, N_shots):
        std = np.sqrt(max(0.0, 1.0 - val**2) / N_shots)
        return val + np.random.normal(0, std)

    def peak_h(h_arr, sig):
        return float(h_arr[np.argmax(sig)])


    n, N_shots, J, dh = 8, 8192, 1.0, 0.05
    h_vals = np.round(np.arange(0.10, 2.51, dh), 10)
    start = time.time()

    sqmz_arr, sa_arr, psi_list = [], [], []
    for h in h_vals:
        H = build_tfim(n, h, J=J)
        _, psi = gs(H)
        sqmz_arr.append(sqmz2(psi, n))
        sa_arr.append(s_ent(psi, n, n // 2))
        psi_list.append(psi)

    sqmz_arr = np.array(sqmz_arr)
    chi_sq = np.abs(np.gradient(sqmz_arr, h_vals))

    # Fidelity susceptibility: chi_F = -2 ln|overlap| / dh^2
    chiF = []
    for i in range(len(h_vals)):
        if i < len(h_vals)-1:
            ov = abs(psi_list[i] @ psi_list[i+1])
            chiF.append(-2.0 * np.log(max(ov, 1e-15)) / dh**2)
        else:
            chiF.append(chiF[-1])
    chiF = np.array(chiF)

    h_c = peak_h(h_vals, chiF)

    true_ph = ["ordered" if h < 1.0 else "paramagnetic" for h in h_vals]
    pred_ph = ["ordered" if h < h_c else "paramagnetic" for h in h_vals]
    pca = sum(t == p for t, p in zip(true_ph, pred_ph)) / len(h_vals)

    np.random.seed(6)
    hc_t = []
    for _ in range(5):
        chiF_n = chiF + np.random.normal(0, 0.05*np.std(chiF), len(chiF))
        hc_t.append(peak_h(h_vals, np.abs(chiF_n)))

    return {
        "estimated_critical_point":     h_c,
        "critical_point_error":         abs(h_c - 1.0),
        "observable_accuracy":          0.0,
        "phase_classification_accuracy": pca,
        "noise_aware_performance":      float(np.std(hc_t)),
        "primary_probes":               ["sqrt_mz2", "fidelity_susceptibility"],
    }

