    pca = sum(t==p for t,p in zip(true_ph,pred_ph)) / len(h_vals)

    np.random.seed(7)
    hc_t = []
    for _ in range(5):
        str_n = np.array([add_noise(v, N_shots) for v in str_arr])
        hc_t.append(peak_h(h_vals, np.abs(np.gradient(str_n, h_vals))))

    return {
        "estimated_critical_point":     h_c,
        "critical_point_error":         abs(h_c - 1.0),
        "observable_accuracy":          0.0,
        "phase_classification_accuracy": pca,
        "noise_aware_performance":      float(np.std(hc_t)),
        "inferred_hamiltonian":         "H=-K*sum sz_{i-1}sx_i sz_{i+1} - h*sum sx_i",
        "primary_probe":                "string_order_parameter",
    }

